mapper.select:
SELECT COUNT(*)
FROM reservation
WHERE s_idx = #{spcIdx}
  AND r_status != 'CANCELLED'
  AND r_start_time < #{resEndTime}
  AND r_end_time   > #{resStartTime}

SELECT COUNT(*)
FROM reservation r
JOIN space s ON r.s_idx = s.s_idx
WHERE r.u_idx  = #{userIdx}
  AND s.b_idx  = #{brnIdx}
  AND r.r_status != 'CANCELLED'

mapper.update:
UPDATE reservation
SET r_status = 'CANCELLED'
WHERE r_idx  = #{resIdx}
  AND u_idx  = #{userIdx}
  AND r_status != 'CANCELLED'
